public class Opportunities extends fflib_SObjectDomain {
    private static final Schema.SObjectField AMOUNT_FIELD =
        Schema.SObjectType.Opportunity.fields.getMap().get('Amount');

    public Opportunities(List<Opportunity> records) {
        super(records);
        Configuration.disableOldOnUpdateValidateBehaviour();
    }

    public class Constructor implements fflib_SObjectDomain.IConstructable {
        public fflib_SObjectDomain construct(List<SObject> records) {
            return new Opportunities((List<Opportunity>) records);
        }
    }

    public override void onValidate() {
        validateNonNegativeAmounts();
    }

    public override void onValidate(Map<Id, SObject> existingRecords) {
        validateNonNegativeAmounts();

        for (Opportunity opp : (List<Opportunity>) Records) {
            Opportunity previous = (Opportunity) existingRecords.get(opp.Id);

            if (previous.StageName == 'Closed Won' &&
                opp.Amount != previous.Amount) {
                error(
                    'Amount cannot change on a won opportunity.',
                    opp,
                    AMOUNT_FIELD
                );
            }
        }
    }

    private void validateNonNegativeAmounts() {
        for (Opportunity opp : (List<Opportunity>) Records) {
            if (opp.Amount != null && opp.Amount < 0) {
                error(
                    'Amount cannot be negative.',
                    opp,
                    AMOUNT_FIELD
                );
            }
        }
    }
}
